#!/bin/bash
# list.sh [--room ROOM] [DATE]: bookings, one per line "DATE START-END ROOM WHO", sorted. src/remind.sh reads this. A malformed DATE exits 2.
set -u
BOOKINGS=${BOOKINGS:-data/bookings.tsv}
room=
if [ "${1:-}" = --room ]; then
  [ $# -ge 2 ] || { echo "usage: list.sh [--room ROOM] [DATE]" >&2; exit 2; }
  room=$2; shift 2
fi
if [ -n "${1:-}" ] && ! [[ "$1" =~ ^[0-9]{4}-[0-9]{2}-[0-9]{2}$ ]]; then echo "bad date: $1 (expected YYYY-MM-DD)" >&2; exit 2; fi
[ -r "$BOOKINGS" ] || { echo "bookings file not found: $BOOKINGS" >&2; exit 2; }
grep -v '^#' "$BOOKINGS" | awk -F'\t' -v d="${1:-}" -v r="$room" 'NF && (d == "" || $2 == d) && (r == "" || $1 == r) { printf "%s %s-%s %s %s\n", $2, $3, $4, $1, $5 }' | sort

#!/bin/bash
fail=0
t=$(mktemp); printf '# h\naoi\t2026-01-01\t10:00\t11:00\tx\nkaede\t2026-01-01\t09:00\t10:00\ty\naoi\t2026-01-02\t13:00\t14:00\tz\n' > "$t"
[ "$(BOOKINGS=$t bash src/list.sh --room aoi)" = "$(printf '2026-01-01 10:00-11:00 aoi x\n2026-01-02 13:00-14:00 aoi z')" ] || { echo "list --room"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh --room aoi 2026-01-01)" = '2026-01-01 10:00-11:00 aoi x' ] || { echo "list --room with date"; fail=1; }
[ -z "$(BOOKINGS=$t bash src/list.sh --room kaede 2026-01-02)" ] || { echo "list --room with a date that has no booking in that room should be empty"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh | head -1)" = '2026-01-01 09:00-10:00 kaede y' ] || { echo "list unchanged"; fail=1; }
err=$(BOOKINGS=$t bash src/list.sh --room 2>&1 >/dev/null); [ $? = 2 ] || { echo "--room without a value should exit 2"; fail=1; }
[ "$err" = 'usage: list.sh [--room ROOM] [DATE]' ] || { echo "--room without a value should print usage: $err"; fail=1; }
rm -f "$t"; exit $fail

